INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind regelmäßige Aktualisierungen von Serverdiensten notwendig, um Sicherheitslücken zu schließen?', 2, '[{"text": "Ja", "correct": true, "because": "Updates beheben Schwachstellen"}, {"text": "Nein", "correct": false, "because": "Sicherheit erfordert Updates"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Aktualisierung von Serverdiensten ohne Neustart erfolgen?', 2, '[{"text": "Ja", "correct": true, "because": "Manche Updates erlauben Live-Patching"}, {"text": "Nein", "correct": false, "because": "Neustart oft nötig, aber nicht immer"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Aktualisierungen immer manuell installiert werden?', 2, '[{"text": "Nein", "correct": true, "because": "Automatische Updates sind möglich"}, {"text": "Ja", "correct": false, "because": "Automatisierung ist üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist eine Testphase vor der Aktualisierung von Serverdiensten empfehlenswert?', 2, '[{"text": "Ja", "correct": true, "because": "Testen verhindert Kompatibilitätsprobleme"}, {"text": "Nein", "correct": false, "because": "Testphase ist Best Practice"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Aktualisierungen die Verfügbarkeit von Serverdiensten beeinträchtigen?', 2, '[{"text": "Ja", "correct": true, "because": "Neustarts oder Fehler können Ausfälle verursachen"}, {"text": "Nein", "correct": false, "because": "Verfügbarkeit kann betroffen sein"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Tool wird oft verwendet, um Aktualisierungen auf einem Linux-Server zu verwalten?', 2, '[{"text": "apt", "correct": true, "because": "apt verwaltet Pakete auf Debian-Systemen"}, {"text": "ping", "correct": false, "because": "Für Netzwerktests"}, {"text": "notepad", "correct": false, "because": "Kein Verwaltungstool"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist der Hauptgrund für die Aktualisierung von Serverdiensten?', 3, '[{"text": "Sicherheitsverbesserung", "correct": true, "because": "Updates schließen Schwachstellen"}, {"text": "Optische Änderungen", "correct": false, "because": "Nicht primär relevant"}, {"text": "Hardwareoptimierung", "correct": false, "because": "Nicht Hauptaufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wird empfohlen, um die Auswirkungen von Updates zu minimieren?', 2, '[{"text": "Testen in einer Staging-Umgebung", "correct": true, "because": "Verhindert Produktionsprobleme"}, {"text": "Sofortige Installation", "correct": false, "because": "Riskant ohne Test"}, {"text": "Ignorieren von Updates", "correct": false, "because": "Unsicher"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Protokoll wird häufig für die Übertragung von Updates verwendet?', 2, '[{"text": "HTTPS", "correct": true, "because": "Sicherer Download von Updates"}, {"text": "ICMP", "correct": false, "because": "Für Diagnosen"}, {"text": "UDP", "correct": false, "because": "Weniger üblich für Updates"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Zeitpunkt ist ideal für die Aktualisierung von Serverdiensten?', 2, '[{"text": "Wartungsfenster", "correct": true, "because": "Minimiert Ausfallzeiten"}, {"text": "Hauptgeschäftszeit", "correct": false, "because": "Stört Nutzer"}, {"text": "Zufälliger Zeitpunkt", "correct": false, "because": "Unplanmäßig riskant"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte sollten bei der Aktualisierung von Serverdiensten überprüft werden?', 4, '[{"text": "Kompatibilität mit bestehender Software", "correct": true, "because": "Verhindert Konflikte"}, {"text": "Sicherheitsupdates", "correct": true, "because": "Schließt Schwachstellen"}, {"text": "Verfügbarkeitsanforderungen", "correct": true, "because": "Minimiert Ausfälle"}, {"text": "Farbe der Benutzeroberfläche", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Tools können für die Aktualisierung von Serverdiensten verwendet werden?', 3, '[{"text": "Windows Server Update Services (WSUS)", "correct": true, "because": "Für Windows-Server"}, {"text": "yum", "correct": true, "because": "Für Red Hat-basierte Systeme"}, {"text": "apt", "correct": true, "because": "Für Debian-basierte Systeme"}, {"text": "ping", "correct": false, "because": "Für Netzwerktests"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Aktualisierung von Serverdiensten?', 4, '[{"text": "Erhöhte Sicherheit", "correct": true, "because": "Schwachstellen werden behoben"}, {"text": "Verbesserte Leistung", "correct": true, "because": "Optimierungen möglich"}, {"text": "Neue Funktionen", "correct": true, "because": "Updates bringen Features"}, {"text": "Höhere Hardwarekosten", "correct": false, "because": "Kein Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte gehören zur Planung einer Serverdienst-Aktualisierung?', 3, '[{"text": "Backup erstellen", "correct": true, "because": "Schützt vor Datenverlust"}, {"text": "Test in Staging-Umgebung", "correct": true, "because": "Prüft Kompatibilität"}, {"text": "Wartungsfenster festlegen", "correct": true, "because": "Minimiert Ausfallzeiten"}, {"text": "Sofortige Installation", "correct": false, "because": "Riskant ohne Planung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken können bei der Aktualisierung von Serverdiensten auftreten?', 3, '[{"text": "Kompatibilitätsprobleme", "correct": true, "because": "Neue Versionen können Konflikte verursachen"}, {"text": "Dienstunterbrechungen", "correct": true, "because": "Neustarts möglich"}, {"text": "Sicherheitslücken", "correct": false, "because": "Updates schließen Lücken"}, {"text": "Datenverlust", "correct": true, "because": "Ohne Backup möglich"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Aktualisierungen verbessern die Sicherheit. b) Updates erfordern immer einen Neustart.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Sicherheit ja, Neustart nicht immer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Eine Testphase vor Updates ist empfohlen. b) Aktualisierungen können automatisch erfolgen.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "Testphase ja, Automatisierung möglich"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch richtig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) WSUS verwaltet Windows-Updates. b) Updates sind nur für neue Funktionen nötig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "WSUS ja, Updates auch für Sicherheit"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Ein Wartungsfenster minimiert Ausfallzeiten. b) HTTPS wird für sichere Update-Downloads genutzt.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "Wartungsfenster ja, HTTPS sicher"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch richtig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Backups sind vor Updates wichtig. b) Aktualisierungen erhöhen immer die Leistung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Backups ja, Leistung nicht immer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

